 readonly TextBlock quotaText=Text("Codex 额度等待采样",11);
 readonly TextBlock readings=Text("等待有效采样…",12),source=Text("",10),exitText=Text("尚未查询公网出口",12),exitState=Text("",11);
 readonly Canvas chart=new Canvas{Height=60,ClipToBounds=true,Background=BrushOf("#E7EDF0")};
 readonly Dictionary<string,ProgressBar> bars=new Dictionary<string,ProgressBar>();readonly Dictionary<string,TextBlock> labels=new Dictionary<string,TextBlock>();
 readonly List<SystemSample> history=new List<SystemSample>();readonly DispatcherTimer outside=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(80)};
