 Button AddButton(Panel p,string label,Action action){var b=new Button{Content=label,Padding=new Thickness(10,5,10,5),Margin=new Thickness(0,5,6,0),BorderThickness=new Thickness(0)};p.Children.Add(b);b.Click+=(s,e)=>action();return b;}
 public MonitorCard():this(new MonitorConfig(),null){}
 public MonitorCard(MonitorConfig cfg,Action persist){config=cfg;save=persist;Title="柯南 · 侦探监控情报";Width=494;SizeToContent=SizeToContent.Height;MaxHeight=SystemParameters.WorkArea.Height;ResizeMode=ResizeMode.NoResize;WindowStyle=WindowStyle.None;AllowsTransparency=true;ShowInTaskbar=false;Topmost=true;FontFamily=new FontFamily("Microsoft YaHei UI");Background=Brushes.Transparent;Foreground=BrushOf("#E2ECF8");BuildDesign();
  countdownTimer.Tick+=(s,e)=>UpdateQuota();
  Deactivated+=(s,e)=>{if(!confirming)Dismiss();};Closed+=(s,e)=>{closed=true;outside.Stop();countdownTimer.Stop();};Loaded+=(s,e)=>{previousDown=(GetAsyncKeyState(1)&0x8000)!=0;outside.Start();countdownTimer.Start();if(config.ExitLookupEnabled&&Environment.GetEnvironmentVariable("CONAN_PET_TEST_MODE")!="1")RefreshExit();};outside.Tick+=(s,e)=>{if(confirming)return;bool down=(GetAsyncKeyState(1)&0x8000)!=0||(GetAsyncKeyState(2)&0x8000)!=0;if(down&&!previousDown){CursorPoint p;if(GetCursorPos(out p)){var point=PointFromScreen(new Point(p.X,p.Y));if(point.X<0||point.Y<0||point.X>ActualWidth||point.Y>ActualHeight){Dismiss();return;}}}previousDown=down;if(config.ExitLookupEnabled&&DateTime.UtcNow>=nextQuery&&Environment.GetEnvironmentVariable("CONAN_PET_TEST_MODE")!="1")RefreshExit();};
