 protected override void OnClosing(System.ComponentModel.CancelEventArgs e){closing=true;base.OnClosing(e);if(e.Cancel)closing=false;}
 void Dismiss(){if(closed||closing||dismissQueued)return;dismissQueued=true;Dispatcher.BeginInvoke(new Action(()=>{dismissQueued=false;if(!closed&&!closing&&!confirming)Close();}));}
 bool ConfirmLookup(string message){confirming=true;try{return MessageBox.Show(this,message,"网络出口查询",MessageBoxButton.YesNo,MessageBoxImage.Question)==MessageBoxResult.Yes;}finally{confirming=false;}}
 async void RefreshExit(){if(querying||closed)return;if(!config.ExitLookupEnabled){exitState.Text="请先启用出口查询（会说明属地服务与发送内容）";return;}querying=true;exitFresh=false;flag.Opacity=.45;exitState.Foreground=BrushOf("#A9CBE5");exitState.Text="正在核验出口…（连接超时8秒）";try{var result=await Task.Run(()=>NetworkExit.Fetch(config.ExitProxyMode,config.ExitProxyAddress));if(closed||!config.ExitLookupEnabled)return;currentExit=result;exitFresh=true;ShowExit(result);flag.Opacity=1;exitState.Foreground=BrushOf(String.IsNullOrEmpty(config.ExpectedExitIp)?"#A9CBE5":result.Ip==config.ExpectedExitIp?"#8DD6B2":"#F0C17E");exitState.Text=result.Status(config)+"\n核验于 "+result.CheckedUtc.ToLocalTime().ToString("HH:mm:ss");}catch(Exception e){if(e is System.Net.WebException||e is System.IO.IOException||e is ArgumentException||e is InvalidOperationException){if(!closed&&config.ExitLookupEnabled){flag.Opacity=.35;exitState.Foreground=BrushOf("#F0C17E");exitState.Text="出口查询不可用 · "+NetworkExit.Failure(e)+"\n当前通道："+(config.ExitProxyMode=="manual"?"手动 HTTP 代理":config.ExitProxyMode=="direct"?"直连":"Windows 系统代理（每次重新读取）");if(currentExit!=null)exitState.Text+="\n上方是旧记录："+currentExit.CheckedUtc.ToLocalTime().ToString("HH:mm:ss");}}else throw;}finally{querying=false;nextQuery=DateTime.UtcNow.AddSeconds(60);}}
 public void Update(SystemSample s){latestSample=s;UpdateQuota();networkDetails.Text=s==null?"网络连接暂不可用":s.NetworkDetails+"\n柯南监控运行："+s.MonitorUptime.ToString(@"dd\天\ hh\:mm\:ss");if(s==null){foreach(string key in bars.Keys){bars[key].Opacity=.35;labels[key].Text="—";}readings.Text="采样暂不可用 · 等待恢复";source.Text="数据未更新，旧数值已隐藏";return;}foreach(var key in bars.Keys){var v=MonitorEngine.Value(s,key);bars[key].Value=v.HasValue?Math.Max(0,Math.Min(100,v.Value)):0;bars[key].Opacity=v.HasValue?1:.35;labels[key].Text=MonitorEngine.Format(s,key);}readings.Text="↓ "+MonitorEngine.Format(s,"download")+"     ↑ "+MonitorEngine.Format(s,"upload")+"\nCPU "+MonitorEngine.Format(s,"cpuTemp")+" · GPU "+MonitorEngine.Format(s,"gpuTemp")+" · 磁盘读 "+Telemetry.Speed(s.DiskRead)+" / 写 "+Telemetry.Speed(s.DiskWrite);source.Text="内存 "+s.MemoryUsed.ToString("F1")+" / "+s.MemoryTotal.ToString("F1")+" GiB · CPU "+(s.CpuMHz.HasValue?s.CpuMHz.Value.ToString("F0")+" MHz":"频率不可用")+"\n"+s.GpuName+(s.VramUsed.HasValue&&s.VramTotal.HasValue?" · 显存 "+s.VramUsed.Value.ToString("F0")+" / "+s.VramTotal.Value.ToString("F0")+" MiB":"")+"\n"+s.NetworkName+" · "+s.Utc.ToLocalTime().ToString("HH:mm:ss")+"\n"+s.TemperatureState;
  if(history.Count==0||history[history.Count-1].Utc!=s.Utc){if(history.Count>0&&s.Utc<history[history.Count-1].Utc)history.Clear();history.Add(s);if(history.Count>60)history.RemoveAt(0);DrawTrend();}}
 void DrawTrend(){chart.Children.Clear();if(history.Count<2||chart.ActualWidth<1){chart.Children.Add(Text("等待连续有效采样…",11));return;}double max=history.Max(s=>Math.Max(s.Download??0,s.Upload??0));max=Math.Max(1024,max);foreach(bool download in new[]{true,false}){Polyline line=null;for(int i=0;i<history.Count;i++){double? v=download?history[i].Download:history[i].Upload;if(!v.HasValue||(i>0&&(history[i].Utc-history[i-1].Utc).TotalSeconds>10))line=null;if(!v.HasValue)continue;if(line==null){line=new Polyline{Stroke=BrushOf(download?"#69CBDE":"#E5B978"),StrokeThickness=1.5};chart.Children.Add(line);}line.Points.Add(new Point(i*chart.ActualWidth/(history.Count-1),56-Math.Min(1,v.Value/max)*52));}}}
 void UpdateQuota(){var s=latestSample;var q=s==null?null:s.Quota;bool fresh=s!=null&&DateTime.UtcNow>=s.Utc&&DateTime.UtcNow-s.Utc<=TimeSpan.FromMilliseconds(Math.Max(5000,config.RefreshMilliseconds*3));if(!fresh){quotaText.Text="额度采样暂不可用 · 等待恢复";foreach(var b in quotaBars.Values){b.Value=0;b.Opacity=.35;}foreach(var label in quotaLabels.Values)label.Text="—";return;}
  var now=DateTime.UtcNow;quotaText.Text=q==null?"等待额度采样":q.State+(q.CheckedUtc==default(DateTime)?"":"\n最近核验："+q.CheckedUtc.ToLocalTime().ToString("MM-dd HH:mm:ss"));
  foreach(int minutes in new[]{300,10080}){var value=q==null?null:q.Remaining(minutes,now);var w=q==null?null:q.Windows.FirstOrDefault(x=>x.Minutes==minutes);quotaBars[minutes].Value=value??0;quotaBars[minutes].Opacity=value.HasValue?1:.35;quotaLabels[minutes].Text=TaskbarPainter.QuotaValue(q,minutes,new TaskbarAppearance(),now)+(value.HasValue&&w!=null?"\n预计重置："+w.ResetUtc.ToLocalTime().ToString("MM-dd HH:mm:ss"):"");}
  if(q!=null&&!q.RequiresAuthorization&&q.NextCheckUtc!=default(DateTime))quotaText.Text+="\n"+(q.NextCheckUtc>now?"下次核验："+(q.NextCheckUtc-now).ToString(@"mm\:ss"):"等待本轮核验返回");
 }
 public static Point Place(Rect body,Size card,Rect area){double x=body.Right+10;if(x+card.Width>area.Right)x=body.Left-card.Width-10;return new Point(Math.Max(area.Left,Math.Min(area.Right-card.Width,x)),Math.Max(area.Top,Math.Min(area.Bottom-card.Height,body.Top+18)));}
