 public void Near(Window pet){if(TaskbarAnchor.HasValue){var r=TaskbarAnchor.Value;var src=PresentationSource.FromVisual(this)??PresentationSource.FromVisual(pet);var matrix=src==null?Matrix.Identity:src.CompositionTarget.TransformFromDevice;var screen=System.Windows.Forms.Screen.FromRectangle(r).WorkingArea;var anchorArea=new Rect(matrix.Transform(new Point(screen.Left,screen.Top)),matrix.Transform(new Point(screen.Right,screen.Bottom)));var anchor=matrix.Transform(new Point(r.Left,r.Top));MaxHeight=anchorArea.Height;Left=Math.Max(anchorArea.Left,Math.Min(anchorArea.Right-Width,anchor.X));Top=Math.Max(anchorArea.Top,Math.Min(anchorArea.Bottom-(ActualHeight>0?ActualHeight:600),anchor.Y-(ActualHeight>0?ActualHeight:600)-8));return;}var source=PresentationSource.FromVisual(pet);var from=source==null?Matrix.Identity:source.CompositionTarget.TransformFromDevice;var to=source==null?Matrix.Identity:source.CompositionTarget.TransformToDevice;var physical=to.Transform(new Point(pet.Left+pet.Width/2,pet.Top+pet.Height/2));var area=System.Windows.Forms.Screen.FromPoint(new System.Drawing.Point((int)physical.X,(int)physical.Y)).WorkingArea;var working=new Rect(from.Transform(new Point(area.Left,area.Top)),from.Transform(new Point(area.Right,area.Bottom)));double scale=(pet.Height-90)/208;var body=new Rect(pet.Left+(pet.Width-192*scale)/2,pet.Top+90,192*scale,208*scale);var canvas=pet.Content as Canvas;var sprite=canvas==null?null:canvas.Children.OfType<SpriteView>().FirstOrDefault();if(sprite!=null&&!sprite.VisibleBounds().IsEmpty){var local=sprite.TransformToAncestor(pet).TransformBounds(sprite.VisibleBounds());body=new Rect(pet.Left+local.X,pet.Top+local.Y,local.Width,local.Height);}var p=Place(body,new Size(Width,ActualHeight>0?ActualHeight:560),working);Left=p.X;Top=p.Y;MaxHeight=working.Height;}
